from text_adventure_games import games, things, actions, blocks
from text_adventure_games.npc import make_hybrid_behavior, make_follow_behavior


class ActionCastleIII(games.Game):
    def __init__(self, start_at, player, characters=None, custom_actions=None):
        super().__init__(start_at, player, characters, custom_actions)

    def is_won(self) -> bool:
        if self.game_over:
            return True
        for name, character in self.characters.items():
            if character.get_property("is_hero") == True:
                msg = "Word of your exploits travels far and wide across the land. You retire as a hero, celebrated by everyone you meet. TO BE CONTINUED!".format(
                    name=character.name.title()
                )
                self.game_over = True
                self.game_over_description = msg
                self.parser.ok(msg)
                return True
        return False


