class Cast_Sleep(actions.Action):
    ACTION_NAME = "cast sleep"
    ACTION_DESCRIPTION = "Cast the Spell of Sleep on the bandits"
    ACTION_ALIASES = []
    PLAYER_CUSTOM = True

    def __init__(self, game, command, actor=None):
        super().__init__(game, actor=actor)
        self.character = self.acting_character(command)
        self.bandits = self.game.characters.get("bandits")

    def check_preconditions(self) -> bool:
        if self.character.location.name != "Bandit Camp":
            self.parser.fail("Nothing happens.")
            return False
        if self.bandits is None or self.bandits.location is not self.character.location:
            self.parser.fail("There's no one here to put to sleep.")
            return False
        if self.bandits.get_property("is_unconscious") or self.bandits.get_property(
            "is_dead"
        ):
            self.parser.fail("The bandits are already out cold.")
            return False
        return True

    def apply_effects(self):
        self.parser.ok(
            "You cast the Spell of Sleep! The bandits slump to the ground, "
            "fast asleep. You can now take the bow."
        )
        self.bandits.set_property("is_unconscious", True)
        # Move the bow out of the bandits' inventory and onto the ground so
        # a subsequent ``take bow`` resolves it. Items in an NPC's inventory
        # are otherwise out of reach for the player's GET action.
        bow = self.bandits.inventory.get("bow")
        if bow is not None:
            self.bandits.remove_from_inventory(bow)
            self.character.location.add_item(bow)


