    dwarf.set_property("is_poisoned", True)
    dwarf.set_property("is_freed", False)
    dwarf.set_property("is_healed", False)
    dwarf.set_property("emotional_state", "weak")
    hatchet = things.Item(
        "hatchet",
        "a sturdy hatchet",
        "A sturdy hatchet. Good for chopping through webs.",
    )
    hatchet.set_property("is_weapon", True)
    dwarf.add_to_inventory(hatchet)
    pickaxe = things.Item("pickaxe", "a heavy pickaxe", "A heavy mining pickaxe.")
