    custom_actions = [
        Cast_Sleep,
        Cook_Stew,
        Fill_Waterskin,
        Invite_Elf,
        Invite_Wizard,
        Invite_Cleric,
        Invite_Dwarf,
        Shoot_Spider,
        Free_Dwarf,
        Heal_Dwarf,
        Show_Baby,
        Pick_Lock,
        Look_Up,
        Free_Cleric,
        Turn_Undead,
        Throw_Javelin,
        Push_Cultist,
        Use_Telescope,
        Search_Dungeon,
        Spider_Hiss,
        Spider_Attack,
        Demon_Roar,
        Demon_Destroy,
        Cultist_Sneer,
        Cultist_Chant,
        Skeleton_Menace,
        Skeleton_Attack,
        Go_Home,
        Fight_Bandits,
    ]

    return ActionCastleIII(crossroads, player, characters, custom_actions)


